182: export function towerStats(def, level) {
183:   const s = { ...def.base };
184:   for (let i = 0; i < level && i < def.upgrades.length; i++) {
185:     const mods = def.upgrades[i].mods;
186:     for (const [k, v] of Object.entries(mods)) {
187:       if (k.endsWith("Mul")) {
188:         const key = k.slice(0, -3);
189:         s[key] = (s[key] ?? 1) * v;
190:       } else if (typeof v === "number") {
191:         s[k] = (s[k] ?? 0) + v;
192:       }
193:     }
194:   }
195:   return s;
196: }
