198: // Wave composition. Deterministic and tuned for a 40-wave run.
199: const UNLOCK = [
200:   [1, "red"], [3, "blue"], [5, "green"], [7, "yellow"], [10, "pink"],
201:   [13, "black"], [15, "white"], [17, "zebra"], [19, "rainbow"], [22, "ceramic"],
202: ];
203: 
204: export function unlockedTypes(round) {
205:   return UNLOCK.filter(([r]) => round >= r).map(([, t]) => t);
206: }
207: 
208: export function buildWave(round) {
209:   const unlocked = unlockedTypes(round);
210:   const newest = unlocked.slice(-3);
211:   const queue = [];
212:   const add = (type, count, start, gap) => {
213:     for (let i = 0; i < count; i++) queue.push({ type, time: start + i * gap });
214:   };
215: 
216:   if (round === 1) {
217:     add("red", 10, 0, 0.62);
218:     return queue.sort((a, b) => a.time - b.time);
219:   }
220:   if (round === 2) {
221:     add("red", 14, 0, 0.5);
222:     return queue.sort((a, b) => a.time - b.time);
223:   }
224: 
225:   const heavyScale = { red: 1, blue: 0.9, green: 0.8, yellow: 0.7, pink: 0.62, black: 0.55, white: 0.55, zebra: 0.44, rainbow: 0.32, ceramic: 0.2 };
226:   const base = Math.min(120, Math.round((8 + round * 2.1) * 0.85));
227:   const gap = Math.max(0.24, 0.54 - round * 0.006);
228: 
229:   // Lead group: the newest unlocked bloon. Then support groups of older tiers.
230:   const lead = newest[newest.length - 1];
231:   const leadCount = Math.max(2, Math.round(base * (heavyScale[lead] ?? 0.5)));
232:   add(lead, leadCount, 0, lead === "ceramic" ? gap * 1.35 : gap);
233: 
234:   if (newest.length > 1) {
235:     const mid = newest[newest.length - 2];
236:     const midCount = Math.max(3, Math.round(base * 0.35 * (heavyScale[mid] ?? 0.5)));
237:     add(mid, midCount, 1.1, gap * 0.8);
238:   }
239:   if (round >= 12 && newest.length > 2) {
240:     const low = newest[0];
241:     const lowCount = Math.max(4, Math.round(base * 0.3));
242:     add(low, lowCount, 5.5, gap);
243:   }
244: 
245:   // MOAB bosses every 5 rounds from 25.
246:   if (round >= 25 && round % 5 === 0) {
247:     const moabs = 1 + Math.floor((round - 25) / 10);
248:     for (let i = 0; i < moabs; i++) {
249:       queue.push({ type: "moab", time: 2.5 + i * 4.2 });
250:     }
251:   }
252: 
253:   return queue.sort((a, b) => a.time - b.time);
254: }
