263: // Small deterministic RNG for map decoration.
264: export function mulberry32(seed) {
265:   return function () {
266:     seed |= 0;
267:     seed = (seed + 0x6d2b79f5) | 0;
268:     let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
269:     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
270:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
271:   };
272: }

