input.newString:
togglePause() {
  if (!this.game.started || this.game.over || this.game.victory) return;
  if (this.overlayOpen) {
    if (this.overlayMode === "pause") {
      this.hideOverlay();
      this.game.paused = false;
    }
    return;
  }
  if (this.game.paused) {
    this.game.paused = false;
    this.el.pause.classList.remove("on");
  } else {
    this.game.paused = true;
    this.el.pause.classList.add("on");
    this.showPause();
  }
  this.game.emit("ui");
}

closeHelp() {
  if (this.overlayMode !== "help") return;
  this.hideOverlay();
  if (this.helpWasPaused && this.game.started && !this.game.over && !this.game.victory) {
    this.game.paused = true;
    this.el.pause.classList.add("on");
    this.showPause();
  } else {
    this.game.paused = false;
  }
  this.helpWasPaused = false;
  this.game.emit("ui");
}

