await page.evaluate('() => {
  const {game, track} = window.__bloonPatrol;
  const { MAX_ROUND } = { MAX_ROUND: 40 };
  game.reset();
  game.started = true;
  game.cash = 700;
  const spots = [];
  for (let d = 130; d < track.length - 110; d += 85) {
    const p = track.pointAt(d), n = track.normalAt(d);
    for (const s of [-1, 1]) {
      const x = p.x + n.x * 64 * s, y = p.y + n.y * 64 * s;
      if (game.placementInfo('dart', x, y).valid) { spots.push([x, y]); break; }
    }
  }
  const buyOrder = ['dart','dart','tack','boomerang','bomb','ice','sniper','ninja','wizard','dart','bomb','sniper','wizard','super','ninja','bomb','ice','sniper','wizard','super'];
  const maxTowers = 20;
  let spotIdx = 0;
  function tryBuyTower() {
    if (game.towers.length >= maxTowers || spotIdx >= spots.length) return false;
    for (const id of buyOrder) {
      const def = window.__bloonPatrol.game.towers.length >= 0 ? null : null;
      const cost = {dart:200,tack:350,boomerang:450,bomb:600,ice:500,sniper:420,ninja:560,wizard:700,super:3800}[id];
      if (game.cash < cost) continue;
      // enforce order index: don't spam super before it's in sequence
      game.armTower(id);
      for (let attempt = 0; attempt < 8 && spotIdx < spots.length; attempt++, spotIdx++) {
        const [x,y] = spots[spotIdx];
        if (game.tryPlaceAt(x,y)) return true;
      }
      game.disarmTower();
      return false;
    }
    return false;
  }
  function tryUpgrade() {
    const candidates = game.towers
      .filter(t => t.level < 3)
      .map(t => ({t, cost:t.def.upgrades[t.level].cost}))
      .filter(o => o.cost <= game.cash)
      .sort((a,b)=>a.cost-b.cost);
    if (!candidates.length) return false;
    const t = candidates[0].t;
    game.selected = t;
    game.upgradeSelected();
    game.selected = null;
    return true;
  }
  // initial purchases
  for (let i=0;i<3;i++){ if (!tryBuyTower()) break; }
  let steps=0, error=null, waveLog=[];
  try {
    while (game.round <= 40 && !game.over && !game.victory && steps < 200000) {
      // spend phase
      let safety = 0;
      while (safety++ < 20) {
        if (!tryUpgrade() && !tryBuyTower()) break;
      }
      // start wave
      if (!game.roundActive) {
        waveLog.push({r:game.round, cash:game.cash, towers:game.towers.length, lives:game.lives, levels:game.towers.map(t=>t.level).join('')});
        game.startRound();
      }
      const before = game.round;
      let guard=0;
      while (game.roundActive && !game.over && !game.victory && guard++ < 30000) {
        game.update(0.05); steps++;
      }
      if (game.round === before && game.roundActive) break;
    }
  } catch(e) { error = String(e && e.stack || e); }
  return JSON.stringify({victory:game.victory, over:game.over, round:game.round, lives:game.lives, popped:game.popped, leaked:game.leaked, towers:game.towers.length, steps, error, lastWaves:waveLog.slice(-6)});
}');
